package com.example.ZCHackathon.commerce; import com.example.ZCHackathon.product.Product; import com.example.ZCHackathon.suggestion.*; import org.springframework.stereotype.Component; import java.math.*;
@Component public class RuleBasedCommerceAdvisor implements CommerceAdvisor {public String key(){return "rule";}public CommerceRecommendation recommend(Product p,double avg,TriggerReason t){boolean low=p.getStockLevel()<p.getReorderThreshold(),spike=p.getDemandVelocity()>avg*2;PriceDirection d=(low||spike)?PriceDirection.INCREASE:PriceDirection.HOLD;BigDecimal price=d==PriceDirection.INCREASE?p.getCurrentPrice().multiply(BigDecimal.valueOf(low?1.10:1.05)).setScale(2,RoundingMode.HALF_UP):p.getCurrentPrice();String why=low?"Stock is below its reorder threshold. Increase price modestly to protect scarce inventory while replenishment is arranged.":spike?"Demand velocity is over twice the category average. Increase price modestly to capture exceptional demand.":"Inventory and demand are stable, so hold the current price.";return new CommerceRecommendation(price,d,low?.86:spike?.78:.68,why,Math.max(1,p.getReorderThreshold()*3-p.getStockLevel()),.82,"Order enough stock to reach three reorder-threshold cycles and protect against ongoing demand.");}}
